$recent=db()->query('SELECT p.*,c.name category_name FROM photos p LEFT JOIN categories c ON c.id=p.category_id WHERE p.deleted_at IS NULL ORDER BY p.created_at DESC LIMIT 6')->fetchAll();
$popular=db()->query('SELECT c.*,COUNT(p.id) photo_count FROM categories c LEFT JOIN photos p ON p.category_id=c.id AND p.deleted_at IS NULL GROUP BY c.id ORDER BY photo_count DESC,c.name LIMIT 5')->fetchAll();
